// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: deposit amount (uint256) and a boolean to choose whether owner reverts on receive
    function testFuzz_property(uint256 depositAmount, bool ownerIsReverter) public {
        // keep depositAmount within a reasonable gas-safe bound but wide
        depositAmount = bound(depositAmount, 0, 1 ether);

        // Deploy either a normal payable owner or a reverter owner
        address owner;
        Reverter reverter;
        PayableOwner payableOwner;
        if (ownerIsReverter) {
            reverter = new Reverter();
            owner = address(reverter);
        } else {
            payableOwner = new PayableOwner();
            owner = address(payableOwner);
        }

        // Fund the owner so it can be set as msg.sender when creating a new C in setUp was already done
        // We need to make calls as the owner to the already deployed c, so set the contract's owner by
        // deploying a fresh C where the deployer is our desired owner. To adhere to the requirement that
        // c is deployed in setUp() using new C(), we instead transfer ownership by calling sendMoney as owner
        // is immutable here; instead we will simulate behavior by having the owner call withdrawAll on c.

        // First, deposit funds to c by sending Ether to fallback
        if (depositAmount > 0) {
            vm.deal(address(this), depositAmount);
            // send into c via fallback
            (bool s, ) = address(c).call{value: depositAmount}("");
            require(s);
        }

        // The reference contract's owner is the deployer (this test contract). We need to test withdrawAll when
        // msg.sender == owner. So we must call withdrawAll as the original owner (this contract). The distinguishing
        // behavior arises when the recipient (msg.sender) of the transfer during withdrawAll reverts on receive.
        // Therefore we will have the owner (this contract) call an intermediate function that uses tx.origin or
        // similar? But since C sets owner at deployment to the deployer (setUp), owner is this test contract.
        // To simulate calling withdrawAll but having the final recipient be an external address that may revert, we
        // exploit that withdrawAll sends to msg.sender (the caller), so we need the caller to be the adversarial contract.
        // Thus we impersonate the adversarial owner by creating a separate C instance deployed by that adversary.

        // Deploy a fresh contract c2 whose owner is the adversarial owner (so the owner is the caller who deploys c2)
        C c2;
        if (ownerIsReverter) {
            vm.prank(address(reverter));
            c2 = new C();
        } else {
            vm.prank(address(payableOwner));
            c2 = new C();
        }

        // Deposit funds into c2
        if (depositAmount > 0) {
            vm.deal(address(this), depositAmount);
            (bool s2, ) = address(c2).call{value: depositAmount}("");
            require(s2);
        }

        // Now call withdrawAll as the owner (the adversarial contract). The transfer will attempt to send Ether to the caller
        // (the adversarial contract). We capture whether the call succeeded.
        bool ok;
        if (ownerIsReverter) {
            // owner will revert on receive, so the withdrawAll call should revert; call via try/catch
            vm.prank(address(reverter));
            try c2.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // owner accepts funds; call and expect success
            vm.prank(address(payableOwner));
            try c2.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Single assertion reading c2's public state: when the owner reverts on receive, withdrawAll should fail and
        // c2's balance should remain equal to depositAmount; when the owner accepts, c2's balance should be zero.
        // This is the universal property the reference satisfies; the mutant changing withdrawAll to directly transfer
        // may alter this behavior for some inputs.
        if (ownerIsReverter) {
            assertTrue(address(c2).balance == depositAmount);
        } else {
            assertTrue(address(c2).balance == 0);
        }
    }
}

// Helper contracts
contract Reverter {
    receive() external payable { revert("no accept"); }
    fallback() external payable { revert("no accept"); }
}

contract PayableOwner {
    receive() external payable {}
    fallback() external payable {}
}

