pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositAmount (amount to deposit into C) and attackerIsContract (0 or 1)
    // We will deploy either an EOA-like owner (use address derived from vm.addr) or a malicious contract OwnerReenter
    function testFuzz_property(uint256 depositAmount, uint8 attackerIsContract) public {
        // keep depositAmount within reasonable bounds and allow zero too
        depositAmount = bound(depositAmount, 0, 1 ether);
        // attackerIsContract should be 0 or 1
        attackerIsContract = attackerIsContract % 2;

        // Prepare owner: either an EOA address or a re-entering contract
        address ownerAddr;
        OwnerReenter attacker;
        if (attackerIsContract == 1) {
            attacker = new OwnerReenter(address(c));
            ownerAddr = address(attacker);
        } else {
            // create an EOA-like address by deriving a private key and address
            uint256 pk = uint256(keccak256(abi.encodePacked(address(this), depositAmount)));
            ownerAddr = vm.addr(pk);
        }

        // Fund the owner so it can receive and send if needed
        vm.deal(ownerAddr, 2 ether);

        // Set c.owner to ownerAddr by deploying c with default owner, then impersonate to transfer ownership is not available.
        // Instead we need to make calls as the current owner to set up: the deployed c's owner is this test contract.
        // So we must simulate the scenario by deploying a fresh contract where owner is the desired address.
        // Workaround: deploy a new C with constructor called by ownerAddr via vm.prank
        vm.prank(ownerAddr);
        C localC = new C();

        // deposit funds to localC from some depositor
        address depositor = vm.addr(0xBEEF);
        vm.deal(depositor, 2 ether);
        vm.prank(depositor);
        // deposit by sending Ether to fallback
        (bool sent, ) = address(localC).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // If attacker is contract, let it know deposit amount to decide reentrancy timing
        if (attackerIsContract == 1) {
            attacker.setTarget(address(localC));
        }

        // Now perform withdrawAll as the ownerAddr (either EOA via vm.prank or contract calling withdrawAll)
        bool ok;
        vm.prank(ownerAddr);
        try localC.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct reference C, after owner calls withdrawAll the contract balance is zero iff the transfer to owner succeeded (ok==true) — but to make a single assertion that distinguishes mutant, we assert that if the call did not revert then the balance must be zero.
        // This holds for the reference contract for all admissible inputs; the mutant will be found by fuzzing where the call returns true but balance is non-zero.
        if (ok) {
            assertTrue(address(localC).balance == 0);
        } else {
            // If call reverted, we do not assert anything (kept wide). To satisfy the requirement of a single assertion reading c, we only assert in the ok case.
            assertTrue(true);
        }
    }
}

// Minimal adversarial contract that attempts re-entrancy on receive
contract OwnerReenter {
    address public target;
    bool public entered;
    constructor(address _target) payable {
        target = _target;
    }
    function setTarget(address _t) external {
        target = _t;
    }
    // receive will try to call withdrawAll on target once to attempt re-entrancy
    receive() external payable {
        if (!entered) {
            entered = true;
            // attempt to re-enter
            try C(payable(target)).withdrawAll() {
            } catch {}
        }
    }
}

