contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: deposit amount and a boolean indicating whether owner will revert on receive
    // We fuzz deposit to let the fuzzer find amounts where balances/transfer edge cases matter.
    function testFuzz_property(uint256 depositAmount, bool ownerReverts) public {
        // keep deposit in a reasonable range but wide
        depositAmount = bound(depositAmount, 0, 1 ether);

        // deploy an adversarial owner contract that can either accept or revert on receive
        AttackerOwner owner = new AttackerOwner(ownerReverts);

        // fund the depositor EOA and the attacker owner so they can send/receive
        address depositor = address(0xBEEF);
        vm.deal(depositor, depositAmount);
        vm.deal(address(owner), 1 ether);

        // make the contract's owner be the AttackerOwner by deploying c from this test and then
        // we need c.owner to be the msg.sender at construction; setUp() created c from this contract,
        // so replace c by redeploying from the attacker owner using low-level create; to do that,
        // have the attackerOwner deploy a fresh C and replace c with it.
        vm.prank(address(owner));
        C fresh = new C();
        c = fresh;

        // deposit funds into c via fallback by sending Ether from depositor
        vm.prank(depositor);
        (bool sent,) = address(c).call{value: depositAmount}('');
        require(sent || depositAmount == 0); // ensure deposit succeeded when amount > 0

        // Now as the owner (attacker contract), call withdrawAll
        vm.prank(address(owner));
        // try/catch to call and record whether it reverted
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (observed via a single assertTrue reading c):
        // For the correct contract C, after the owner calls withdrawAll, the contract's balance is zero
        // iff the transfer to the owner succeeded. Since ok indicates whether withdrawAll completed,
        // the reference implementation always results in address(c).balance == 0 when ok == true,
        // and balance unchanged when ok == false. We assert that when the call returned (ok==true),
        // the contract balance is zero. This holds for the reference for all inputs; the mutant is
        // distinguishable because some adversarial owner behaviours + deposit amounts make this fail.
        assertTrue(!ok || address(c).balance == 0);
    }
}

// Adversarial owner contract: can be configured to revert on receive or to accept and optionally re-enter.
contract AttackerOwner {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    // receive either reverts or accepts funds
    receive() external payable {
        if (shouldRevert) revert("owner reverts");
        // otherwise accept
    }
}

