pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: an amount to deposit/send and an address that will attempt to call withdrawAll
    function testFuzz_property(uint96 depositAmount, address caller) public {
        // keep depositAmount in a reasonable wide range but non-zero
        depositAmount = uint96(bound(depositAmount, 1, type(uint96).max));
        // ensure caller is not the owner (owner is address(this) from setUp deploy), let fuzzer explore both owner and non-owner
        vm.assume(caller != address(0));

        // Fund the contract by sending Ether to its fallback (increments depositsCount)
        // The contract's fallback is payable: we make the test contract send ETH to c
        vm.deal(address(this), depositAmount);
        // send depositAmount to c so its balance increases
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "funding failed");

        // record balance before withdrawAll
        uint256 before = address(c).balance;

        // have the fuzzed caller attempt to call withdrawAll
        vm.deal(caller, 1 ether); // ensure caller has funds for tx
        vm.startPrank(caller);
        bool ok;
        try c.withdrawAll{value:0}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // After the call, for the correct contract P: if caller is not owner, withdrawAll must NOT have withdrawn funds
        // We express a universal property: for ANY depositAmount and ANY caller, if caller != owner then contract balance remains equal to before.
        // Single assertion reading c: if caller != owner then address(c).balance == before
        if (caller != address(this)) {
            assertTrue(address(c).balance == before);
        } else {
            // if caller is the owner, withdrawAll may succeed and drain funds; still assertTrue on a property the reference satisfies for ALL inputs
            // For owner calls, the reference may change balance; to keep a single assertTrue as required, use a tautology that still reads c: balance >= 0
            assertTrue(address(c).balance >= 0);
        }
    }
}

